        *_single_aggregations("dysarthria_nih_stroke_scale", "CODED"),
        *_single_aggregations("dysarthria_score_stroke", "NUMERIC"),
        *_single_aggregations("limb_ataxia_nih_stroke_scale", "CODED"),
        *_single_aggregations("limb_ataxia_score_stroke", "NUMERIC"),
        *_single_aggregations("extinction_score_stroke", "NUMERIC"),
